const wheelChromaSampleCache=new Map();
function wheelChromaSamples(sampleL,zoom){
 const density=Math.max(1,Math.min(2.5,Math.floor(zoom*2)/2)),sampleStep=5/density,sampleRadius=sampleStep*.3;
 const key=[sampleL,density,Number(colorWheelShowAll),Number(!!state.vfxLock)].join(':');
 if(wheelChromaSampleCache.has(key)){
  const cached=wheelChromaSampleCache.get(key);wheelChromaSampleCache.delete(key);wheelChromaSampleCache.set(key,cached);return cached;
 }
 let svg='';const extent=Math.floor(50/sampleStep);
 for(let iy=-extent;iy<=extent;iy++)for(let ix=-extent;ix<=extent;ix++){
  const x=ix*sampleStep,y=iy*sampleStep;if(x*x+y*y>2500)continue;
  const a=x/.55,b=-y/.55,fit=fitLabToSRGB(sampleL,a,b),color=labColor(fit.l,fit.a,fit.b),outside=labColor(sampleL,a,b).outside;
  svg+=`<circle class="wheel-chroma-sample" cx="${110+x}" cy="${91+y}" r="${sampleRadius}" fill="${color.hex}" fill-opacity="${(colorWheelShowAll?.22:1)*(state.vfxLock&&outside?.18:1)}" data-outside-srgb="${outside}" pointer-events="none"><title>L* ${sampleL} · C* ${Math.hypot(a,b).toFixed(1)}</title></circle>`;
 }
 wheelChromaSampleCache.set(key,svg);
 if(wheelChromaSampleCache.size>12)wheelChromaSampleCache.delete(wheelChromaSampleCache.keys().next().value);
 return svg;
}

function wheelChromaSamples(sampleL,zoom){
 const project=p=>({x:110+p.a*.55,y:91-p.b*.55});
 return `<defs><clipPath id="wheel-color-surface-disc"><circle cx="110" cy="91" r="50"/></clipPath></defs><g data-wheel-color-surface opacity="${colorWheelShowAll?.22:1}" clip-path="url(#wheel-color-surface-disc)">${window.AtlasLabSurface.svg(sampleL,labColor,fitLabToSRGB,project,'wheel')}</g>`;
}
